   pub struct Point64 { pub x: i64, pub y: i64 }  // Copy; Point64::new(x,y)
   pub type Path64 = Vec<Point64>;
   pub type Paths64 = Vec<Path64>;
   pub struct Rect64 { pub left: i64, pub top: i64, pub right: i64, pub bottom: i64 }
   pub enum FillRule { EvenOdd, NonZero, Positive, Negative }
   pub fn union(paths: &Paths64, fr: FillRule) -> Paths64;
   pub fn intersect(a: &Paths64, b: &Paths64, fr: FillRule) -> Paths64;
   pub fn difference(a: &Paths64, b: &Paths64, fr: FillRule) -> Paths64;
   pub fn xor(a: &Paths64, b: &Paths64, fr: FillRule) -> Paths64;
   pub fn area(path: &Path64) -> f64;            // signed area, Clipper2 convention
   pub fn get_bounds(paths: &Paths64) -> Rect64;
   pub fn translate_paths(paths: &Paths64, dx: i64, dy: i64) -> Paths64;
   // src/offset.rs
   pub enum JoinType { Round, Miter, Square, Bevel }
   pub enum EndType { Polygon, Joined, Butt, Round, Square }
