```rust
fn shl_bits(a: &mut Vec<u32>, bits: u32) {
    let words = (bits / 32) as usize;
    let rem = bits % 32;
    if rem > 0 {
        let mut carry = 0u32;
        for limb in a.iter_mut() {
            let new_carry = *limb >> (32 - rem);
            *limb = (*limb << rem) | carry;
            carry = new_carry;
        }
        if carry > 0 { a.push(carry); }
    }
    if words > 0 {
        // insert zeros at the bottom
        let mut shifted = vec![0u32; words];
        shifted.extend_from_slice(a);
        *a = shifted;
    }
}
```

pow5_mul: mul by 5^13 chunks then remainder:
```rust
fn pow5_mul(a: &mut Vec<u32>, k: u32) {
    const CHUNK: u32 = 13;
    const POW5_13: u32 = 1220703125; // 5^13
    let chunks = k / CHUNK;
    let rem = k % CHUNK;
    for _ in 0..chunks { mul_small(a, POW5_13); }
    let mut r = 1u32;
    for _ in 0..rem { r *= 5; }
    if r > 1 { mul_small(a, r); }
}

fn mul_small(a: &mut Vec<u32>, x: u32) {
    let mut carry = 0u64;
    for limb in a.iter_mut() {
        let t = (*limb as u64) * (x as u64) + carry;
        *limb = t as u32;
        carry = t >> 32;
    }
    while carry > 0 { a.push(carry as u32); carry >>= 32; }
}
```

