/// Mimics C++ `std::stoi`: skips leading whitespace, optional sign, parses a
/// leading run of decimal digits and ignores trailing junk.
fn stoi(s: &str) -> i32 {
    let bytes = s.trim_start().as_bytes();
    let mut idx = 0;
    let mut sign = 1i64;
    if idx < bytes.len() && (bytes[idx] == b'+' || bytes[idx] == b'-') {
        if bytes[idx] == b'-' {
            sign = -1;
        }
        idx += 1;
    }
    let mut val: i64 = 0;
    while idx < bytes.len() && bytes[idx].is_ascii_digit() {
        val = val * 10 + (bytes[idx] - b'0') as i64;
        idx += 1;
    }
    (sign * val) as i32
}

fn main() {
    // 20个API：终极综合测试
    let args: Vec<String> = std::env::args().collect();
    let complexity: i32 = if args.len() > 1 {
        std::cmp::min(stoi(&args[1]), 5)
    } else {
        3
    };

    // 创建多层次复杂几何
    let mut geometry_layers: Vec<Paths64> = Vec::new();

    // 第1层：基础形状
    let mut layer1: Paths64 = Vec::new();
    for i in 0..complexity as i64 {
        // 圆形
        let mut circle: Path64 = Vec::new();
        for j in 0..24i64 {
            let angle = 2.0 * 3.1415926 * j as f64 / 24.0;
            let x = 100 + i * 80 + (40.0 * angle.cos()) as i64;
            let y = 100 + (40.0 * angle.sin()) as i64;
            circle.push(Point64::new(x, y));
        }
        layer1.push(circle);

        // 正方形
        let mut square: Path64 = Vec::new();
        let size: i64 = 50 + i * 10;
        square.push(Point64::new(200 + i * 60, 200));
        square.push(Point64::new(200 + i * 60 + size, 200));
        square.push(Point64::new(200 + i * 60 + size, 200 + size));
        square.push(Point64::new(200 + i * 60, 200 + size));
        layer1.push(square);
    }
    geometry_layers.push(layer1);

    // 第2层：复杂多边形
    let mut layer2: Paths64 = Vec::new();
    for i in 0..complexity as i64 {
        // 星形
        let mut star: Path64 = Vec::new();
        let points: i64 = 5 + i;
        for j in 0..points * 2 {
            let angle = 2.0 * 3.1415926 * j as f64 / (points * 2) as f64;
            let radius = if j % 2 == 0 { 35.0 } else { 20.0 };
            let x = 150 + (radius * angle.cos()) as i64;
            let y = 150 + i * 100 + (radius * angle.sin()) as i64;
            star.push(Point64::new(x, y));
        }
        layer2.push(star);

        // 螺旋形
        let mut spiral: Path64 = Vec::new();
        for j in 0..30i64 {
            let t = j as f64 * 0.3;
            let radius = 10.0 + t * 4.0;
            let angle = t;
            let x = 300 + (radius * angle.cos()) as i64;
            let y = 150 + i * 100 + (radius * angle.sin()) as i64;
            spiral.push(Point64::new(x, y));
        }
        layer2.push(spiral);
    }
    geometry_layers.push(layer2);

    // 第3层：网格和图案
    let mut layer3: Paths64 = Vec::new();
    for i in 0..complexity as i64 {
        for j in 0..complexity as i64 {
            // 六边形网格
            let mut hex: Path64 = Vec::new();
            let center_x: i64 = 50 + i * 70;
            let center_y: i64 = 300 + j * 70;
            for k in 0..6i64 {
                let angle = 2.0 * 3.1415926 * k as f64 / 6.0;
                let x = center_x + (25.0 * angle.cos()) as i64;
                let y = center_y + (25.0 * angle.sin()) as i64;
                hex.push(Point64::new(x, y));
            }
            layer3.push(hex);

            // 三角形
            let mut triangle: Path64 = Vec::new();
            triangle.push(Point64::new(center_x + 100, center_y));
            triangle.push(Point64::new(center_x + 100 + 30, center_y + 50));
            triangle.push(Point64::new(center_x + 100 - 30, center_y + 50));
            layer3.push(triangle);
        }
    }
    geometry_layers.push(layer3);

    // 执行20个API操作链
    let mut accumulated: Paths64 = Vec::new();

    // 1-3. 每层独立并集
    for layer in &geometry_layers {
        let union_layer = clipper::r#union(layer, FillRule::EvenOdd);
        accumulated.extend(union_layer);
    }

    // 4. 所有层合并
    let all_union = clipper::r#union(&accumulated, FillRule::EvenOdd);

    // 5-8. 分层处理
    let mut processed: Paths64 = Vec::new();
    for i in 0..geometry_layers.len() {
        let layer_union = clipper::r#union(&geometry_layers[i], FillRule::EvenOdd);

        // 与其他层交互
        for j in i + 1..geometry_layers.len() {
            let other_union = clipper::r#union(&geometry_layers[j], FillRule::EvenOdd);

            // 5. 交集
            let intersect = clipper::intersect(&layer_union, &other_union, FillRule::EvenOdd);
            // 6. 差集
            let diff = clipper::difference(&layer_union, &other_union, FillRule::EvenOdd);
            // 7. 异或
            let xorbit = clipper::xor(&layer_union, &other_union, FillRule::EvenOdd);

            processed.extend(intersect);
            processed.extend(diff);
            processed.extend(xorbit);
        }
    }

    // 9. 处理结果合并
    let all_processed = clipper::r#union(&processed, FillRule::NonZero);

    // 10-13. 偏移操作序列
    let mut offset_results: Paths64 = Vec::new();
    let offsets = [2.0, -1.5, 3.0, -2.0];

    for i in 0..4 {
        let join_type = match i {
            0 => JoinType::Round,
            1 => JoinType::Miter,
            2 => JoinType::Square,
            _ => JoinType::Bevel,
        };
        let offset = offset::inflate_paths(&all_processed, offsets[i], join_type, EndType::Polygon);
        offset_results.extend(offset);
    }

    // 14. 偏移结果合并
    let union_offsets = clipper::r#union(&offset_results, FillRule::EvenOdd);

    // 15. 与原始并集交互
    let final_intersect = clipper::intersect(&union_offsets, &all_union, FillRule::EvenOdd);
    let final_diff = clipper::difference(&union_offsets, &all_union, FillRule::EvenOdd);
    let final_xor = clipper::xor(&union_offsets, &all_union, FillRule::EvenOdd);

    // 16. 合并所有最终结果
    let mut all_final: Paths64 = Vec::new();
    all_final.extend(final_intersect);
    all_final.extend(final_diff);
    all_final.extend(final_xor);

    // 17. 最终并集
    let final_union = clipper::r#union(&all_final, FillRule::NonZero);

    // 18. 平移归一化
    let bounds = clipper::get_bounds(&final_union);
    let normalized = clipper::translate_paths(&final_union, -bounds.left, -bounds.top);

    // 19. 最终偏移
    let last_offset = offset::inflate_paths(&normalized, 1.0, JoinType::Round, EndType::Polygon);

    // 20. 综合计算
    let mut total_area: f64 = 0.0;
    let mut total_perimeter: f64 = 0.0;
    let mut total_vertices: i64 = 0;

    for path in &last_offset {
        let area = clipper::area(path);
        total_area += area;
        total_vertices += path.len() as i64;

        // 估算周长（简单方法）
        if path.len() > 1 {
            for i in 0..path.len() {
                let j = (i + 1) % path.len();
                let dx = (path[j].x - path[i].x) as f64;
                let dy = (path[j].y - path[i].y) as f64;
                total_perimeter += (dx * dx + dy * dy).sqrt();
            }
        }
    }

    let complexity_score = total_area * 0.7 + total_perimeter * 0.2 + total_vertices as f64 * 0.1;

    println!("{}", cppfmt::format_cpp_double(complexity_score));
}

