    EvenOdd,
    NonZero,
    Positive,
    Negative,
}
pub fn r#union(paths: &Paths64, _fr: FillRule) -> Paths64 {
    paths.clone()
}
pub fn intersect(_a: &Paths64, _b: &Paths64, _fr: FillRule) -> Paths64 {
    Vec::new()
}
pub fn difference(a: &Paths64, _b: &Paths64, _fr: FillRule) -> Paths64 {
    a.clone()
}
pub fn xor(a: &Paths64, b: &Paths64, _fr: FillRule) -> Paths64 {
    let mut r = a.clone();
    r.extend(b.iter().cloned());
    r
}
pub fn area(path: &Path64) -> f64 {
    let mut s: i128 = 0;
    for i in 0..path.len() {
        let j = (i + 1) % path.len();
        s += path[i].x as i128 * path[j].y as i128 - path[j].x as i128 * path[i].y as i128;
    }
    s as f64 / 2.0
}
pub fn get_bounds(paths: &Paths64) -> Rect64 {
    let mut r = Rect64 { left: i64::MAX, top: i64::MAX, right: i64::MIN, bottom: i64::MIN };
    for p in paths {
        for pt in p {
            r.left = r.left.min(pt.x);
            r.top = r.top.min(pt.y);
            r.right = r.right.max(pt.x);
            r.bottom = r.bottom.max(pt.y);
        }
    }
    r
}
pub fn translate_paths(paths: &Paths64, dx: i64, dy: i64) -> Paths64 {
    paths
        .iter()
        .map(|p| p.iter().map(|pt| Point64::new(pt.x + dx, pt.y + dy)).collect())
        .collect()
}

